/**
 * Packet-scan QA (test A5): four photos sent to a running app's /api/scan. Images are generated by
 * scripts/make-scan-images.py into eval/scan/ (drawn packs, no real brands).
 * Run: node scripts/qa-scan.ts [base url]
 */
import { readFileSync, writeFileSync } from "node:fs";

const base = process.argv[2] ?? "https://will-it-suit-me.vercel.app";
const dataUrl = (f: string) => `data:image/jpeg;base64,${readFileSync(new URL(`../eval/scan/${f}`, import.meta.url)).toString("base64")}`;
type Want = (r: { match: string; id: string | null }) => boolean;
const CASES: [string, string, Want][] = [
  ["exact pack (Purrfect Bowl, chicken in gravy, adult)", "chicken.jpg", (r) => r.match === "exact" && r.id === "cat-chicken-gravy"],
  ["same brand, flavour not stocked (salmon)", "salmon.jpg", (r) => r.match !== "exact" && r.id === null],
  ["not a product (a landscape)", "landscape.jpg", (r) => r.match !== "exact"],
  ["blank photo", "blank.jpg", (r) => r.match !== "exact"],
];
const rows = [];
for (const [name, file, ok] of CASES) {
  const t0 = Date.now();
  const res = await fetch(`${base}/api/scan`, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ image: dataUrl(file) }) });
  const body = await res.json();
  const ms = Date.now() - t0;
  const r = body.result as { match: string; id: string | null; alternatives: string[]; note: string | null } | undefined;
  // A handled refusal ("couldn't read that photo") is also a pass for the non-product and blank cases.
  const pass = r ? ok(r) : (res.status === 502 && !name.startsWith("exact") && !name.startsWith("same"));
  rows.push({ name, status: res.status, ms, pass, result: r ?? body });
  console.log(`${pass ? "PASS" : "FAIL"} A5 ${name}: ${res.status} ${r ? `${r.match} ${r.id ?? "-"} alts=${r.alternatives.join(",")}` : body.error} (${ms} ms)`);
  await new Promise((rs) => setTimeout(rs, 5000));
}
const passed = rows.filter((r) => r.pass).length;
console.log(`\n${passed}/${rows.length} passed`);
writeFileSync(new URL("../eval/qa-scan-results.json", import.meta.url),
  JSON.stringify({ base, run_at: new Date().toISOString(), passed, total: rows.length, rows }, null, 1) + "\n");
